import{_ as t,o as r,c as a,a2 as o}from"./chunks/framework.D7WGirly.js";const u=JSON.parse('{"title":"Publishing and recovery","description":"","frontmatter":{},"headers":[],"relativePath":"releasing.md","filePath":"releasing.md"}'),n={name:"releasing.md"};function i(s,e,d,l,c,p){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="publishing-and-recovery" tabindex="-1">Publishing and recovery <a class="header-anchor" href="#publishing-and-recovery" aria-label="Permalink to &quot;Publishing and recovery&quot;">​</a></h1><p>The <code>NPM publish</code> workflow runs on <code>master</code> pushes or a manual dispatch from <code>master</code>. It uses a GitHub-hosted Ubuntu runner, Node 24, npm 11.13.0, and OIDC trusted publishing. It has no <code>NPM_TOKEN</code> requirement. <code>id-token: write</code> is granted only to the publishing job; repository contents remain read-only. Publishing is serialized and concurrent runs are not cancelled.</p><h2 id="one-time-npm-setup" tabindex="-1">One-time npm setup <a class="header-anchor" href="#one-time-npm-setup" aria-label="Permalink to &quot;One-time npm setup&quot;">​</a></h2><p>In the npm package Settings page, add a GitHub Actions trusted publisher:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Value</th></tr></thead><tbody><tr><td>Organization/user</td><td><code>miladezzat</code></td></tr><tr><td>Repository</td><td><code>encrypt-rsa</code></td></tr><tr><td>Workflow filename</td><td><code>publish.yml</code> (filename only)</td></tr><tr><td>Environment</td><td>Empty; the workflow currently uses no GitHub environment</td></tr><tr><td>Allow npm publish</td><td>Enabled</td></tr><tr><td>Allow npm dist-tag</td><td>Disabled</td></tr></tbody></table><p>The package&#39;s <code>repository</code> URL must match the GitHub repository. If a protected GitHub environment is added later, update the npm connection and workflow together. OIDC uses short-lived workflow credentials; do not substitute a local token into the publish step. npm requires a recent npm CLI/Node version and a supported hosted runner. See <a href="https://docs.npmjs.com/trusted-publishers/" target="_blank" rel="noreferrer">npm trusted publishing</a>.</p><h2 id="release-behavior" tabindex="-1">Release behavior <a class="header-anchor" href="#release-behavior" aria-label="Permalink to &quot;Release behavior&quot;">​</a></h2><p>Prepare a stable <code>major.minor.patch</code> version in <code>package.json</code> and the lockfile, update the changelog/docs, and open a reviewed PR. The registry guard fetches npm&#39;s <code>latest</code> version without authentication. An unchanged version skips publishing and verifies the exact existing release, an older local version fails, and a newer version runs all package/browser/docs and AI example checks before <code>npm publish --access public</code>. HTTP errors, malformed registry data, and network failures stop the release instead of assuming the package is unpublished. Prerelease versions require a separate release policy.</p><p>Merging the PR starts the release. After npm accepts a publish, it may spend several minutes processing the package before public reads succeed. The workflow polls the exact-version endpoint for up to ten minutes and verifies version/name/integrity, retrying temporary 404, rate-limit/server, and network failures, including interrupted or timed-out HTTP-200 response bodies. Body transport failures use the same bounded deadline and backoff as header failures. Permanent authentication errors, malformed JSON, or invalid metadata fail immediately. Verification never republishes. OIDC automatically creates provenance for supported public GitHub repositories. An npm version is immutable: later fixes need a new version. Local tests and dry runs do not verify an actual registry publish.</p><h2 id="recover-a-failed-run" tabindex="-1">Recover a failed run <a class="header-anchor" href="#recover-a-failed-run" aria-label="Permalink to &quot;Recover a failed run&quot;">​</a></h2><p>For <code>E401</code> in the old <code>npm whoami</code> step, the repository token was rejected. The OIDC workflow removes that token path. Re-running the old workflow still uses its old code; merge this workflow before dispatching a fresh run on <code>master</code>.</p><p>If OIDC fails, check the exact repository, filename, optional environment, allowed direct publish action, Node/npm versions, job <code>id-token</code> permission, and hosted runner against the npm connection. Do not print authentication environment variables or tokens to diagnose it. If a publish succeeded but a later verification step failed, confirm the exact version on npm and retry a fresh dispatch; the guard skips an already published version.</p><p>If npm is unavailable, retry once registry service recovers. If the proposed version was previously published under another tag, choose a fresh stable version rather than trying to overwrite it. Remove an obsolete token secret only after the first OIDC release succeeds; account token revocation is a separate owner action.</p>',13)])])}const m=t(n,[["render",i]]);export{u as __pageData,m as default};
